<script setup>
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import PublicLayout from '../../layouts/PublicLayout.vue'; import { createLoginForm, handleLogin, loginBenefits, loginFields, roleOptions, validateLogin } from '../../data/common/login'
const router=useRouter(); const form=reactive(createLoginForm()); const errors=ref({}); function submit(){errors.value=validateLogin(form); const result=handleLogin(form); if(result.ok) router.push(result.redirect)}
</script>
<template><PublicLayout><div class="auth-page"><section class="auth-intro"><h1>欢迎使用就业数据研究台</h1><p>登录后可查看岗位趋势、薪资水平、城市机会与专业方向分析。</p><ul><li v-for="item in loginBenefits" :key="item">{{ item }}</li></ul></section><form class="auth-card" @submit.prevent="submit"><h1>用户登录</h1><p>使用账号进入系统</p><label v-for="field in loginFields" :key="field.key"><span class="field-label">{{ field.label }}</span><input v-model="form[field.key]" class="input" :type="field.type" :placeholder="field.placeholder"><span class="field-error">{{ errors[field.key] }}</span></label><label><span class="field-label">角色选择</span><select v-model="form.role" class="select"><option v-for="role in roleOptions" :key="role.value" :value="role.value">{{ role.label }}</option></select></label><label class="remember"><input v-model="form.remember" type="checkbox">记住登录</label><button class="button button-primary submit" type="submit">登录</button><p class="auth-switch">还没有账号？<router-link to="/register">注册账号</router-link></p></form></div></PublicLayout></template>
<style scoped>.auth-page{display:grid;grid-template-columns:minmax(360px,1fr) 420px;gap:80px;align-items:center;max-width:1120px;min-height:calc(100vh - 68px);margin:auto;padding:48px 24px}.auth-intro h1{font-size:34px;color:var(--color-primary-900)}.auth-intro>p{max-width:520px;margin-top:16px;color:var(--color-text-secondary);font-size:16px}.auth-intro ul{display:grid;gap:12px;margin-top:30px;color:var(--color-primary-700)}.auth-card{padding:34px 36px;border:1px solid var(--color-border);border-radius:8px;background:#fff;box-shadow:var(--shadow-float)}.auth-card h1{font-size:24px;color:var(--color-primary-900)}.auth-card>p{margin:4px 0 24px;color:var(--color-text-secondary)}.remember{display:flex;gap:8px;align-items:center;margin:12px 0 20px;color:var(--color-text-secondary)}.submit{width:100%}.auth-switch{text-align:center!important;margin:18px 0 0!important;font-size:13px}.auth-switch a{color:var(--color-info)}@media(max-width:820px){.auth-page{grid-template-columns:1fr;gap:28px}.auth-intro{display:none}.auth-card{width:min(100%,440px);margin:auto;padding:28px 24px}}</style>
